import{_ as n,o as i,c as e,a2 as r}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Rincian Sistem Penjadwalan Yurisprudensi Ruang","description":"","frontmatter":{},"headers":[],"relativePath":"id/0013-空间法理调度体系详解.md","filePath":"id/0013-空间法理调度体系详解.md"}'),t={name:"id/0013-空间法理调度体系详解.md"};function u(s,a,l,d,g,m){return i(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="rincian-sistem-penjadwalan-yurisprudensi-ruang" tabindex="-1">Rincian Sistem Penjadwalan Yurisprudensi Ruang <a class="header-anchor" href="#rincian-sistem-penjadwalan-yurisprudensi-ruang" aria-label="Permalink to &quot;Rincian Sistem Penjadwalan Yurisprudensi Ruang&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Proyek</th><th>Isi</th></tr></thead><tbody><tr><td>Nomor Dokumen</td><td>13</td></tr><tr><td>Modul</td><td>Hukum Alam Semesta dan Sistem Kultivasi</td></tr><tr><td>Kata Kunci Utama</td><td>Yurisprudensi Ruang, Penjadwalan Hukum, Penyeberangan Bidang, Ruang Terisolasi, Tiga Dasar Asal</td></tr></tbody></table><h2 id="i-gambaran-umum-sistem" tabindex="-1">I. Gambaran Umum Sistem <a class="header-anchor" href="#i-gambaran-umum-sistem" aria-label="Permalink to &quot;I. Gambaran Umum Sistem&quot;">​</a></h2><p>Sistem Penjadwalan Yurisprudensi Ruang adalah sistem ketiga dari tiga ratus sistem kultivasi asal, menempati urutan ketiga dalam &quot;Tiga Dasar Asal&quot;, dan merupakan dasar dari semua sistem kultivasi serta aplikasi teknologi yang melibatkan operasi ruang, dimensi, dan bidang. Sistem ini berfokus pada &quot;pemahaman dan penjadwalan hukum ruang&quot;, menekankan persepsi yang akurat dan pengendalian yang teratur terhadap yurisprudensi ruang, bukan sekadar perobekan dan perusakan ruang yang kasar. Sistem Penjadwalan Yurisprudensi Ruang merupakan dasar kultivasi untuk aplikasi penting seperti interaksi antar-bidang, pembangunan ruang terisolasi, teknologi cermin replika, dan pemeliharaan jangkar, memainkan peran yang tak tergantikan dalam pembangunan infrastruktur peradaban simbiosis.</p><p>Sistem Penjadwalan Yurisprudensi Ruang cocok untuk kultivator dengan persepsi ruang yang kuat, pemikiran logis yang cermat, dan yang mengutamakan presisi serta keteraturan. Kultivator sistem ini adalah kelompok bakat teknis paling penting dalam peradaban simbiosis, yang memikul tanggung jawab tugas-tugas krusial seperti pembangunan jangkar, pemeliharaan saluran antar-bidang, pengelolaan ruang terisolasi, dan pembangunan ruang arkeologi.</p><h2 id="ii-prinsip-inti-sistem" tabindex="-1">II. Prinsip Inti Sistem <a class="header-anchor" href="#ii-prinsip-inti-sistem" aria-label="Permalink to &quot;II. Prinsip Inti Sistem&quot;">​</a></h2><p>Prinsip inti dari Sistem Penjadwalan Yurisprudensi Ruang adalah &quot;ruang adalah yurisprudensi, penjadwalan adalah keteraturan&quot;, yang dapat dipahami dari tiga tingkat berikut:</p><h3 id="_2-1-hakikat-yurisprudensi-ruang" tabindex="-1">2.1 Hakikat Yurisprudensi Ruang <a class="header-anchor" href="#_2-1-hakikat-yurisprudensi-ruang" aria-label="Permalink to &quot;2.1 Hakikat Yurisprudensi Ruang&quot;">​</a></h3><p>Dalam pandangan dunia Heng Yuan Zhou, ruang bukanlah wadah kosong, melainkan struktur teratur yang terdiri dari serangkaian aturan yurisprudensial. Atribut seperti dimensi, jarak, arah, kelengkungan, dan stabilitas ruang semuanya ditentukan oleh aturan yurisprudensi ruang yang mendasarinya. Memahami hakikat ruang berarti memahami mekanisme kerja aturan yurisprudensial ini.</p><p>Yurisprudensi ruang dapat dibagi menjadi tiga tingkat: yurisprudensi dasar (menentukan atribut dasar ruang, seperti struktur tiga dimensi, definisi jarak, dll.), yurisprudensi perubahan (menentukan sifat ruang yang dapat berubah, seperti pelipatan ruang, perubahan kelengkungan, dll.), yurisprudensi asal (menentukan penciptaan dan penghancuran ruang, seperti pembentukan dan keruntuhan bidang, dll.). Kultivasi Sistem Penjadwalan Yurisprudensi Ruang dimulai dari memahami yurisprudensi dasar, lalu secara bertahap mendalami yurisprudensi perubahan dan yurisprudensi asal.</p><h3 id="_2-2-metode-inti-penjadwalan" tabindex="-1">2.2 Metode Inti Penjadwalan <a class="header-anchor" href="#_2-2-metode-inti-penjadwalan" aria-label="Permalink to &quot;2.2 Metode Inti Penjadwalan&quot;">​</a></h3><p>&quot;Penjadwalan&quot; adalah metodologi inti dari Sistem Penjadwalan Yurisprudensi Ruang. Berbeda dengan &quot;perobekan ruang&quot; dalam kultivasi penjarahan, penjadwalan tidak merusak struktur ruang dengan kekerasan, melainkan melakukan penyesuaian dan pengendalian ruang yang teratur melalui pemahaman dan kepatuhan terhadap yurisprudensi ruang.</p><p>Metode inti penjadwalan meliputi:</p><ul><li><strong>Persepsi Yurisprudensial</strong>: mempersepsikan keadaan kerja aturan yurisprudensial di ruang, mengidentifikasi struktur dan anomali ruang</li><li><strong>Pengarahan Yurisprudensial</strong>: melalui energi dan kesadaran diri sendiri, mengarahkan yurisprudensi ruang untuk bekerja ke arah yang diharapkan</li><li><strong>Resonansi Yurisprudensial</strong>: menghasilkan resonansi dengan yurisprudensi ruang, memperluas efek dan jangkauan penjadwalan</li><li><strong>Stabilisasi Yurisprudensial</strong>: menstabilkan hasil penjadwalan menjadi struktur ruang yang stabil, seperti ruang terisolasi, saluran antar-bidang, dll.</li></ul><p>Kunci penjadwalan terletak pada &quot;bertindak sesuai kecenderungan&quot;. Kultivator bukanlah penguasa ruang, melainkan &quot;penjadwal&quot; yurisprudensi ruang — melalui pemahaman dan kepatuhan terhadap yurisprudensi, mewujudkan pengendalian ruang yang teratur.</p><h3 id="_2-3-prinsip-etika-operasi-ruang" tabindex="-1">2.3 Prinsip Etika Operasi Ruang <a class="header-anchor" href="#_2-3-prinsip-etika-operasi-ruang" aria-label="Permalink to &quot;2.3 Prinsip Etika Operasi Ruang&quot;">​</a></h3><p>Sistem Penjadwalan Yurisprudensi Ruang menetapkan prinsip etika operasi ruang yang ketat:</p><ul><li><strong>Prinsip Intervensi Minimum</strong>: operasi terhadap ruang harus sekecil mungkin, menghindari kerusakan struktur ruang yang tidak perlu</li><li><strong>Prinsip Dapat Dipulihkan</strong>: semua operasi ruang sementara harus mengembalikan keadaan asli ruang setelah selesai, tidak boleh meninggalkan kerusakan permanen</li><li><strong>Prinsip Isolasi</strong>: operasi ruang yang dapat menimbulkan risiko harus dilakukan di ruang terisolasi, mencegah penyebaran risiko</li><li><strong>Prinsip Persetujuan</strong>: operasi ruang tingkat tinggi (seperti penyeberangan bidang, pelipatan ruang, dll.) harus melalui persetujuan dari lembaga pengelola jangkar</li></ul><h2 id="iii-pembagian-alam-dan-ciri-setiap-tahap" tabindex="-1">III. Pembagian Alam dan Ciri Setiap Tahap <a class="header-anchor" href="#iii-pembagian-alam-dan-ciri-setiap-tahap" aria-label="Permalink to &quot;III. Pembagian Alam dan Ciri Setiap Tahap&quot;">​</a></h2><p>Sistem Penjadwalan Yurisprudensi Ruang dibagi menjadi lima alam inti:</p><table tabindex="0"><thead><tr><th>Alam</th><th>Nama</th><th>Ciri Inti</th><th>Jangkauan Kendali Ruang</th><th>Kemampuan Khas</th></tr></thead><tbody><tr><td>Alam Pertama</td><td>Mengenal Ruang</td><td>Mempersepsikan awal keberadaan yurisprudensi ruang, mampu mengidentifikasi struktur dasar ruang</td><td>Jangkauan persepsi seratus meter</td><td>Persepsi Ruang: dapat mempersepsikan keadaan yurisprudensi dan anomali ruang di sekitar</td></tr><tr><td>Alam Kedua</td><td>Mengendalikan Ruang</td><td>Mampu melakukan pengendalian dasar ruang, seperti perpindahan ruang jarak pendek</td><td>Jangkauan kendali sepuluh meter</td><td>Teleportasi Jarak Pendek: dapat melakukan perpindahan ruang dalam jangkauan sepuluh meter</td></tr><tr><td>Alam Ketiga</td><td>Mengubah Ruang</td><td>Mampu mengubah atribut lokal ruang, seperti pelipatan ruang, penyesuaian kelengkungan</td><td>Jangkauan kendali seratus meter</td><td>Pelipatan Ruang: dapat melipat jarak seratus meter menjadi sejauh satu langkah</td></tr><tr><td>Alam Keempat</td><td>Ruang Yurisprudensi</td><td>Mampu membangun struktur ruang yang stabil, seperti ruang terisolasi, ruang penyimpanan</td><td>Jangkauan kendali kilometer</td><td>Pembangunan Ruang Terisolasi: dapat menciptakan ruang mandiri yang stabil untuk kultivasi atau eksperimen</td></tr><tr><td>Alam Kelima</td><td>Ruang Asal</td><td>Menyentuh yurisprudensi asal ruang, mampu melakukan penyeberangan bidang dan pembangunan saluran antar-bidang</td><td>Jangkauan kendali antar-bidang</td><td>Penyeberangan Bidang: dapat melakukan penyeberangan stabil antar-bidang dengan dukungan jangkar</td></tr></tbody></table><p>Penerobosan setiap alam memerlukan kelulusan &quot;Ujian Yurisprudensi Ruang&quot;: menilai kedalaman pemahaman kultivator terhadap yurisprudensi ruang, presisi dan stabilitas kendali ruang, serta kepatuhan terhadap etika operasi ruang; hanya ketika ketiga item memenuhi standar, peningkatan alam dapat dikonfirmasi.</p><h2 id="iv-metode-kultivasi-inti-sistem" tabindex="-1">IV. Metode Kultivasi Inti Sistem <a class="header-anchor" href="#iv-metode-kultivasi-inti-sistem" aria-label="Permalink to &quot;IV. Metode Kultivasi Inti Sistem&quot;">​</a></h2><h3 id="_4-1-metode-kultivasi-persepsi-yurisprudensial" tabindex="-1">4.1 Metode Kultivasi Persepsi Yurisprudensial <a class="header-anchor" href="#_4-1-metode-kultivasi-persepsi-yurisprudensial" aria-label="Permalink to &quot;4.1 Metode Kultivasi Persepsi Yurisprudensial&quot;">​</a></h3><p>Persepsi yurisprudensial adalah dasar dari Sistem Penjadwalan Yurisprudensi Ruang, meliputi:</p><ul><li><strong>Metode Mendengarkan Sunyi Ruang</strong>: di ruang yang sunyi, memejamkan mata dan memusatkan pikiran, mempersepsikan kerja halus yurisprudensi ruang, seolah-olah &quot;mendengarkan&quot; napas ruang</li><li><strong>Metode Identifikasi Anomali</strong>: melakukan pelatihan persepsi di area yang memiliki anomali ruang (seperti retakan ruang, anomali kelengkungan, dll.), meningkatkan kemampuan mengidentifikasi anomali ruang</li><li><strong>Metode Persepsi Multidimensi</strong>: secara bertahap melatih persepsi struktur ruang di luar tiga dimensi, membangun dasar untuk memahami yurisprudensi ruang dimensi tinggi</li><li><strong>Metode Peta Yurisprudensi</strong>: menggambar struktur yurisprudensi ruang yang dipersepsikan menjadi &quot;peta yurisprudensi&quot; dalam kesadaran, meningkatkan kognisi keseluruhan terhadap struktur ruang</li></ul><h3 id="_4-2-metode-kultivasi-kendali-ruang" tabindex="-1">4.2 Metode Kultivasi Kendali Ruang <a class="header-anchor" href="#_4-2-metode-kultivasi-kendali-ruang" aria-label="Permalink to &quot;4.2 Metode Kultivasi Kendali Ruang&quot;">​</a></h3><p>Kendali ruang adalah keterampilan inti sistem, meliputi:</p><ul><li><strong>Metode Pelatihan Mikro-operasi</strong>: memulai pelatihan dari kendali ruang dengan jangkauan terkecil, seperti melipat ruang sepanjang satu sentimeter, secara bertahap meningkatkan presisi dan jangkauan kendali</li><li><strong>Metode Kultivasi Perpindahan</strong>: memulai dari perpindahan ruang jarak pendek, secara bertahap meningkatkan jarak dan kompleksitas perpindahan, akhirnya mewujudkan teleportasi berkelanjutan</li><li><strong>Metode Kultivasi Pelipatan</strong>: melatih kemampuan pelipatan ruang, dari pelipatan garis lurus sederhana hingga pelipatan multidimensi yang kompleks</li><li><strong>Metode Kultivasi Kelengkungan</strong>: melatih kemampuan menyesuaikan kelengkungan ruang; kendali kelengkungan adalah dasar dari teknologi ruang tingkat tinggi</li></ul><h3 id="_4-3-metode-kultivasi-pembangunan-ruang" tabindex="-1">4.3 Metode Kultivasi Pembangunan Ruang <a class="header-anchor" href="#_4-3-metode-kultivasi-pembangunan-ruang" aria-label="Permalink to &quot;4.3 Metode Kultivasi Pembangunan Ruang&quot;">​</a></h3><p>Pembangunan ruang adalah keterampilan tingkat tinggi sistem, meliputi:</p><ul><li><strong>Metode Pembangunan Ruang Penyimpanan</strong>: mempelajari membangun ruang penyimpanan kecil yang stabil, menguasai teknologi stabilisasi batas ruang</li><li><strong>Metode Pembangunan Ruang Terisolasi</strong>: mempelajari membangun ruang mandiri dengan efek isolasi, menguasai teknologi penghalang ruang dan isolasi energi</li><li><strong>Metode Pembangunan Ruang Kultivasi</strong>: mempelajari membangun ruang khusus yang cocok untuk kultivasi, seperti ruang kultivasi dengan aliran waktu yang berbeda, lapangan kultivasi dengan konsentrasi energi yang dapat disesuaikan, dll.</li><li><strong>Metode Pembangunan Saluran Antar-bidang</strong>: dengan dukungan jangkar, mempelajari membangun saluran stabil yang menghubungkan dua bidang</li></ul><h2 id="v-aplikasi-sistem-dalam-peradaban-simbiosis" tabindex="-1">V. Aplikasi Sistem dalam Peradaban Simbiosis <a class="header-anchor" href="#v-aplikasi-sistem-dalam-peradaban-simbiosis" aria-label="Permalink to &quot;V. Aplikasi Sistem dalam Peradaban Simbiosis&quot;">​</a></h2><p>Sistem Penjadwalan Yurisprudensi Ruang memiliki aplikasi yang luas dan penting dalam peradaban simbiosis:</p><h3 id="_5-1-pembangunan-infrastruktur" tabindex="-1">5.1 Pembangunan Infrastruktur <a class="header-anchor" href="#_5-1-pembangunan-infrastruktur" aria-label="Permalink to &quot;5.1 Pembangunan Infrastruktur&quot;">​</a></h3><ul><li><strong>Pembangunan dan Pemeliharaan Jangkar</strong>: kultivator tingkat tinggi dari Sistem Penjadwalan Yurisprudensi Ruang adalah kekuatan inti dalam pembangunan jangkar, bertanggung jawab atas desain dan konstruksi struktur ruang jangkar</li><li><strong>Pemeliharaan Saluran Antar-bidang</strong>: memelihara saluran ruang yang menghubungkan berbagai bidang, memastikan stabilitas dan keamanan saluran</li><li><strong>Pembangunan Ruang Kultivasi Publik</strong>: membangun fasilitas ruang khusus seperti ruang kultivasi publik, ruang persepsi yurisprudensi, dll.</li></ul><h3 id="_5-2-arkeologi-dan-penelitian" tabindex="-1">5.2 Arkeologi dan Penelitian <a class="header-anchor" href="#_5-2-arkeologi-dan-penelitian" aria-label="Permalink to &quot;5.2 Arkeologi dan Penelitian&quot;">​</a></h3><ul><li><strong>Arkeologi Jarak Jauh Cermin Replika</strong>: kultivator yurisprudensi ruang berpartisipasi dalam pembangunan ruang teknologi cermin replika, menyediakan ruang jarak jauh yang terisolasi untuk arkeologi</li><li><strong>Eksperimen Ruang Terisolasi</strong>: menyediakan ruang terisolasi untuk eksperimen yurisprudensi berbahaya dan eksperimen energi, mencegah penyebaran risiko</li><li><strong>Penelitian Ruang Kuno</strong>: meneliti struktur dan teknologi ruang yang ditinggalkan oleh peradaban kuno</li></ul><h3 id="_5-3-aplikasi-kehidupan-sehari-hari" tabindex="-1">5.3 Aplikasi Kehidupan Sehari-hari <a class="header-anchor" href="#_5-3-aplikasi-kehidupan-sehari-hari" aria-label="Permalink to &quot;5.3 Aplikasi Kehidupan Sehari-hari&quot;">​</a></h3><ul><li><strong>Teknologi Penyimpanan Ruang</strong>: menyediakan peralatan penyimpanan ruang untuk masyarakat umum, memudahkan kehidupan sehari-hari</li><li><strong>Medis Ruang</strong>: menggunakan teknologi ruang untuk melakukan operasi medis yang presisi, seperti operasi non-invasif, pengangkatan lesi internal, dll.</li><li><strong>Transportasi Ruang</strong>: sistem transportasi jarak pendek berbasis teknologi pelipatan ruang, secara signifikan meningkatkan efisiensi perjalanan</li></ul><h3 id="_5-4-keamanan-dan-pertahanan" tabindex="-1">5.4 Keamanan dan Pertahanan <a class="header-anchor" href="#_5-4-keamanan-dan-pertahanan" aria-label="Permalink to &quot;5.4 Keamanan dan Pertahanan&quot;">​</a></h3><ul><li><strong>Penghalang Ruang</strong>: membangun penghalang ruang untuk perlindungan fasilitas penting</li><li><strong>Blokade Ruang</strong>: dalam situasi darurat, melakukan blokade ruang pada area tertentu untuk mencegah penyebaran bahaya</li><li><strong>Penyelamatan Ruang</strong>: menggunakan kemampuan perpindahan ruang untuk melakukan penyelamatan darurat, seperti memindahkan orang dengan cepat dari lokasi bencana</li></ul><h2 id="vi-keunggulan-dan-keterbatasan-sistem" tabindex="-1">VI. Keunggulan dan Keterbatasan Sistem <a class="header-anchor" href="#vi-keunggulan-dan-keterbatasan-sistem" aria-label="Permalink to &quot;VI. Keunggulan dan Keterbatasan Sistem&quot;">​</a></h2><h3 id="_6-1-keunggulan" tabindex="-1">6.1 Keunggulan <a class="header-anchor" href="#_6-1-keunggulan" aria-label="Permalink to &quot;6.1 Keunggulan&quot;">​</a></h3><ul><li>Nilai praktis sangat tinggi, merupakan sistem inti yang sangat diperlukan untuk pembangunan infrastruktur peradaban</li><li>Kemampuan kendali ruang memiliki keunggulan besar dalam skenario pertempuran, eksplorasi, penyelamatan, dll.</li><li>Kultivator memiliki status sosial yang tinggi, dengan peluang kerja dan pengembangan yang melimpah</li><li>Integrasi erat dengan aplikasi teknologi, hasil kultivasi dapat langsung dikonversi menjadi produk teknologi</li><li>Setelah kemampuan persepsi ruang meningkat, juga berperan sebagai pendukung dalam kultivasi sistem lain</li></ul><h3 id="_6-2-keterbatasan" tabindex="-1">6.2 Keterbatasan <a class="header-anchor" href="#_6-2-keterbatasan" aria-label="Permalink to &quot;6.2 Keterbatasan&quot;">​</a></h3><ul><li>Memiliki persyaratan bakat tertentu untuk persepsi ruang, tidak semua ras cocok untuk mempraktikkannya</li><li>Peningkatan kekuatan tempur pada tahap awal tidak jelas, kemampuan utama cenderung ke arah pendukung dan teknologi</li><li>Operasi ruang tingkat tinggi memiliki risiko yang relatif tinggi, kesalahan operasi dapat menyebabkan konsekuensi serius seperti retakan ruang</li><li>Penerobosan alam tingkat tinggi memerlukan dukungan jangkar, sulit untuk berkultivasi di area dengan cakupan jangkar yang tidak memadai</li><li>Proses kultivasi relatif membosankan, memerlukan banyak pelatihan kendali yang presisi</li></ul><h2 id="vii-kompatibilitas-dengan-sistem-lain" tabindex="-1">VII. Kompatibilitas dengan Sistem Lain <a class="header-anchor" href="#vii-kompatibilitas-dengan-sistem-lain" aria-label="Permalink to &quot;VII. Kompatibilitas dengan Sistem Lain&quot;">​</a></h2><p>Sistem Penjadwalan Yurisprudensi Ruang memiliki kompatibilitas yang baik dengan sistem lain, terutama:</p><ul><li>Kultivasi bersama dengan Sistem Iterasi Deduksi: dapat mendeduksi berbagai cara penerapan yurisprudensi ruang, meningkatkan presisi dan inovasi kendali ruang</li><li>Kultivasi bersama dengan Sistem Siklus Kehidupan: dapat membangun ruang siklus energi kehidupan khusus, meningkatkan efisiensi kultivasi siklus kehidupan</li><li>Kultivasi bersama dengan sistem tipe Peningkatan Kesadaran: pemahaman yurisprudensi ruang membantu persepsi dan adaptasi kesadaran terhadap ruang dimensi tinggi</li><li>Kultivasi bersama dengan sistem tipe Teknik Terapan: teknologi yurisprudensi ruang adalah cabang penting dari rekayasa yurisprudensi, kultivasi bersama dapat secara signifikan meningkatkan kemampuan rekayasa</li></ul><h2 id="penutup" tabindex="-1">Penutup <a class="header-anchor" href="#penutup" aria-label="Permalink to &quot;Penutup&quot;">​</a></h2><p>Sistem Penjadwalan Yurisprudensi Ruang adalah &quot;batu penjuru ruang&quot; dari peradaban simbiosis Jangkar. Berdasarkan pemahaman mendalam terhadap yurisprudensi ruang dan menggunakan penjadwalan teratur sebagai metode, sistem ini memberikan dukungan teknologi ruang yang sangat diperlukan untuk interaksi antar-bidang, pembangunan infrastruktur, penelitian ilmiah, dan aplikasi kehidupan sehari-hari peradaban. Tujuan akhir dari Sistem Penjadwalan Yurisprudensi Ruang adalah menjadikan kultivator sebagai &quot;penjaga dan pembangun&quot; ruang kosmik, dan berdasarkan pemahaman yurisprudensi ruang, membangun jaringan ruang kosmik yang lebih teratur, lebih terhubung, dan lebih aman.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen Terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen Terkait&quot;">​</a></h2><ul><li>10-三百套本源修炼体系总览 (Gambaran Umum Tiga Ratus Sistem Kultivasi Asal)</li><li>62-空间法理技术实现 (Implementasi Teknologi Yurisprudensi Ruang)</li><li>64-隔离空间构建技术 (Teknologi Pembangunan Ruang Terisolasi)</li></ul>',54)])])}const o=n(t,[["render",u]]);export{p as __pageData,o as default};
